<?php require 'includes/bootstrap.php';$t=$_GET['t']??'';$u=null;if(preg_match('/^[a-f0-9]{64}$/',$t)){$s=$pdo->prepare('SELECT full_name,verified_at FROM users WHERE qr_token=?');$s->execute([$t]);$u=$s->fetch();}function masked(string $n):string{$parts=preg_split('/\s+/',trim($n));return implode(' ',array_map(fn($p)=>mb_substr($p,0,1).str_repeat('•',max(2,mb_strlen($p)-1)),$parts));}$pageTitle='Verify identity';require 'includes/header.php';?><section class="card narrow center"><h1>Identity check</h1><?php if($u&&$u['verified_at']):?><div class="seal">✓</div><h2>Verified account</h2><p><?=e(masked($u['full_name']))?></p><p>No email, photograph, password or financial data is disclosed.</p><?php else:?><div class="seal bad">!</div><h2>Invalid identity link</h2><?php endif?></section><?php require 'includes/footer.php';?>
